// Market Hours Check - 9:30 AM to 4:00 PM ET
// Returns market status + whether this is the 4:00 PM close execution

const now = new Date();
const etString = now.toLocaleString('en-US', { timeZone: 'America/New_York' });
const etDate = new Date(etString);
const hours = etDate.getHours();
const minutes = etDate.getMinutes();
const timeInMinutes = hours * 60 + minutes;

// Market hours: 9:30 AM (570 min) to 4:00 PM (960 min)
const MARKET_OPEN = 9 * 60 + 30;  // 570
const MARKET_CLOSE = 16 * 60;      // 960

const isMarketHours = timeInMinutes >= MARKET_OPEN && timeInMinutes <= MARKET_CLOSE;

if (!isMarketHours) {
  return [];
}

// Check if this is the close execution (3:30-4:00 PM window)
const isCloseExecution = (hours === 15 && minutes >= 30) || hours === 16;

return [{
  json: {
    marketOpen: true,
    isCloseExecution,
    timestamp: etDate.toISOString(),
    etTime: `${hours}:${String(minutes).padStart(2, '0')}`,
    dateStr: now.toISOString().split('T')[0]
  }
}];

// =============================================================
// VOLATILITY REGIME ENGINE
// =============================================================
// Classifies the current volatility regime based on VIX level.
// Detects regime CHANGES by comparing to stored previous regime.
// Generates hedging triggers when thresholds are crossed.
// Calculates 20-day and 50-day VIX averages for context.
//
// Regime Classification:
//   VIX < 15       -> LOW_COMPLACENT
//   VIX 15-25      -> NORMAL
//   VIX 25-35      -> ELEVATED
//   VIX > 35       -> CRISIS
//
// Hedging Triggers:
//   VIX < 18       -> Cheap protection available
//   VIX crosses 25 -> Reduce position sizes 25%
//   VIX crosses 35 -> Crisis mode, halt new positions
//   VIX drops < 20 from above -> Vol normalizing, resume
// =============================================================

// ---- Gather inputs ----
const triggerData = $('Market Hours Check').first().json;

// Try ^VIX first, fall back to VIXY proxy
let vixData;
try {
  const vixIndex = $('FMP VIX Index (^VIX)').first().json;
  const vixArray = Array.isArray(vixIndex) ? vixIndex : [vixIndex];
  vixData = vixArray[0];
} catch (e) {
  // Fallback to VIXY proxy
  const vixyData = $('FMP VIX Quote (VIXY Proxy)').first().json;
  const vixyArray = Array.isArray(vixyData) ? vixyData : [vixyData];
  vixData = vixyArray[0];
}

if (!vixData || !vixData.price) {
  return [{ json: { error: true, message: 'Could not fetch VIX data' } }];
}

// Historical data for averages
let historicalData = [];
try {
  const histRaw = $('FMP VIX Historical (50 Days)').first().json;
  if (histRaw && histRaw.historical) {
    historicalData = histRaw.historical;
  } else if (Array.isArray(histRaw)) {
    historicalData = histRaw;
  }
} catch (e) {
  // Continue without historical data
}

// ---- Load previous state ----
const staticData = $getWorkflowStaticData('global');
const prevState = staticData.volRegimeState || {
  vixLevel: null,
  regime: null,
  termStructure: null,
  lastRegimeChange: null,
  lastNotifiedTriggers: {}
};

// ---- Current VIX values ----
const vixPrice = vixData.price;
const vixChange = vixData.change || 0;
const vixChangePct = vixData.changesPercentage || 0;
const vixDayHigh = vixData.dayHigh || vixPrice;
const vixDayLow = vixData.dayLow || vixPrice;
const vixPrevClose = vixData.previousClose || vixPrice;

// ---- Calculate averages from historical data ----
let vix20DayAvg = null;
let vix50DayAvg = null;
let vix5DayTrend = [];

if (historicalData.length >= 20) {
  const last20 = historicalData.slice(0, 20);
  vix20DayAvg = last20.reduce((sum, d) => sum + d.close, 0) / 20;
}
if (historicalData.length >= 50) {
  const last50 = historicalData.slice(0, 50);
  vix50DayAvg = last50.reduce((sum, d) => sum + d.close, 0) / 50;
}
if (historicalData.length >= 5) {
  vix5DayTrend = historicalData.slice(0, 5).map(d => ({
    date: d.date,
    close: d.close
  })).reverse();
}

// ---- Regime Classification ----
function classifyRegime(vix) {
  if (vix < 15) return 'LOW_COMPLACENT';
  if (vix <= 25) return 'NORMAL';
  if (vix <= 35) return 'ELEVATED';
  return 'CRISIS';
}

function getRegimeLabel(regime) {
  const labels = {
    'LOW_COMPLACENT': 'LOW / COMPLACENT',
    'NORMAL': 'NORMAL',
    'ELEVATED': 'ELEVATED',
    'CRISIS': 'CRISIS'
  };
  return labels[regime] || regime;
}

function getSizingGuidance(regime) {
  const guidance = {
    'LOW_COMPLACENT': 'Standard sizing. INCREASE hedging -- protection is cheap. Consider SPY put spreads.',
    'NORMAL': 'Standard sizing applies. Normal hedging posture.',
    'ELEVATED': 'Reduce new position sizes by 25%. Premium selling more attractive but size conservatively. Review all open positions for delta exposure.',
    'CRISIS': 'Reduce position sizes by 50%. Capital preservation mode. HALT new positions until regime normalizes. Consider closing short premium at a loss rather than risking assignment.'
  };
  return guidance[regime] || 'Review positioning.';
}

const currentRegime = classifyRegime(vixPrice);
const prevRegime = prevState.regime;
const regimeChanged = prevRegime && currentRegime !== prevRegime;

// ---- Trigger Detection ----
const triggers = [];
const prevVix = prevState.vixLevel;
const TRIGGER_COOLDOWN_MS = 4 * 60 * 60 * 1000; // 4 hours between same trigger

function triggerOnCooldown(triggerType) {
  const lastNotified = (prevState.lastNotifiedTriggers || {})[triggerType];
  if (!lastNotified) return false;
  return (Date.now() - lastNotified) < TRIGGER_COOLDOWN_MS;
}

// Regime change trigger
if (regimeChanged) {
  triggers.push({
    type: 'REGIME_CHANGE',
    priority: currentRegime === 'CRISIS' ? 'CRITICAL' : 'HIGH',
    from: getRegimeLabel(prevRegime),
    to: getRegimeLabel(currentRegime),
    detail: `Volatility regime changed from ${getRegimeLabel(prevRegime)} to ${getRegimeLabel(currentRegime)}`
  });
}

// VIX crosses above 25
if (prevVix && prevVix <= 25 && vixPrice > 25 && !triggerOnCooldown('VIX_ABOVE_25')) {
  triggers.push({
    type: 'VIX_ABOVE_25',
    priority: 'HIGH',
    detail: 'VIX crossed ABOVE 25 -- elevated volatility',
    action: 'Reduce new position sizes by 25%. Review open short premium positions.'
  });
}

// VIX crosses above 35
if (prevVix && prevVix <= 35 && vixPrice > 35 && !triggerOnCooldown('VIX_ABOVE_35')) {
  triggers.push({
    type: 'VIX_ABOVE_35',
    priority: 'CRITICAL',
    detail: 'VIX crossed ABOVE 35 -- CRISIS LEVEL',
    action: 'HALT all new positions. Reduce existing positions by 50%. Capital preservation mode. Consider closing short premium at a loss rather than risking assignment.'
  });
}

// VIX drops below 15 (complacency)
if (prevVix && prevVix >= 15 && vixPrice < 15 && !triggerOnCooldown('VIX_BELOW_15')) {
  triggers.push({
    type: 'VIX_BELOW_15',
    priority: 'MEDIUM',
    detail: 'VIX dropped BELOW 15 -- low volatility / complacency',
    action: 'Protection is CHEAP. Consider adding SPY put spread hedge. Standard position sizing.'
  });
}

// VIX drops below 18 (cheap protection)
if (prevVix && prevVix >= 18 && vixPrice < 18 && !triggerOnCooldown('VIX_BELOW_18')) {
  triggers.push({
    type: 'VIX_BELOW_18',
    priority: 'MEDIUM',
    detail: 'VIX dropped BELOW 18 -- cheap protection available',
    action: 'Favorable time to add portfolio hedges. Consider SPY put spread for downside protection.'
  });
}

// VIX drops below 20 from above (normalizing)
if (prevVix && prevVix >= 20 && vixPrice < 20 && !triggerOnCooldown('VIX_NORMALIZING')) {
  triggers.push({
    type: 'VIX_NORMALIZING',
    priority: 'MEDIUM',
    detail: 'VIX dropped BELOW 20 from above -- volatility normalizing',
    action: 'Resume standard position sizing. Vol environment returning to normal.'
  });
}

// VIX rate of change > 20% in a day
if (Math.abs(vixChangePct) > 20 && !triggerOnCooldown('VIX_ROC_20')) {
  triggers.push({
    type: 'VIX_ROC_20',
    priority: 'HIGH',
    detail: `VIX moved ${vixChangePct > 0 ? '+' : ''}${vixChangePct.toFixed(1)}% today -- rapid change`,
    action: vixChangePct > 0
      ? 'Volatility spiking rapidly. Review all positions. Consider reducing delta exposure.'
      : 'Volatility dropping rapidly. Caution -- rapid drops can reverse. Wait for stabilization.'
  });
}

// VIX rate of change > 30% in a day (extreme)
if (Math.abs(vixChangePct) > 30 && !triggerOnCooldown('VIX_ROC_30')) {
  triggers.push({
    type: 'VIX_ROC_30',
    priority: 'CRITICAL',
    detail: `EMERGENCY: VIX moved ${vixChangePct > 0 ? '+' : ''}${vixChangePct.toFixed(1)}% today`,
    action: 'EXTREME vol move. Review ALL positions immediately. No new trades until further notice.'
  });
}

// ---- Update trigger cooldowns ----
const notifiedTriggers = { ...(prevState.lastNotifiedTriggers || {}) };
for (const t of triggers) {
  notifiedTriggers[t.type] = Date.now();
}

// ---- Calculate regime duration ----
let regimeDuration = 'Unknown';
if (regimeChanged) {
  regimeDuration = 'Just started';
} else if (prevState.lastRegimeChange) {
  const durationMs = Date.now() - prevState.lastRegimeChange;
  const durationHours = Math.floor(durationMs / (1000 * 60 * 60));
  const durationDays = Math.floor(durationHours / 24);
  if (durationDays > 0) {
    regimeDuration = `${durationDays} day${durationDays > 1 ? 's' : ''}`;
  } else {
    regimeDuration = `${durationHours} hour${durationHours !== 1 ? 's' : ''}`;
  }
}

// ---- Save updated state ----
staticData.volRegimeState = {
  vixLevel: vixPrice,
  regime: currentRegime,
  termStructure: null, // updated if Massive.com data available
  lastRegimeChange: regimeChanged ? Date.now() : (prevState.lastRegimeChange || Date.now()),
  lastNotifiedTriggers: notifiedTriggers,
  lastUpdate: Date.now()
};

// ---- Build output ----
return [{
  json: {
    vixPrice,
    vixChange,
    vixChangePct,
    vixDayHigh,
    vixDayLow,
    vixPrevClose,
    vix20DayAvg: vix20DayAvg ? parseFloat(vix20DayAvg.toFixed(2)) : null,
    vix50DayAvg: vix50DayAvg ? parseFloat(vix50DayAvg.toFixed(2)) : null,
    vix5DayTrend,
    currentRegime,
    currentRegimeLabel: getRegimeLabel(currentRegime),
    prevRegime: prevRegime ? getRegimeLabel(prevRegime) : 'N/A (first run)',
    prevVixLevel: prevVix,
    regimeChanged,
    regimeDuration,
    sizingGuidance: getSizingGuidance(currentRegime),
    triggers,
    hasTriggers: triggers.length > 0,
    isCloseExecution: triggerData.isCloseExecution,
    timestamp: triggerData.etTime,
    dateStr: triggerData.dateStr
  }
}];

// =============================================================
// FORMAT TRIGGER ALERT FOR TELEGRAM
// =============================================================
// Formats regime change and hedging trigger alerts.
// =============================================================

const data = $input.first().json;
const triggers = data.triggers;

if (!triggers || triggers.length === 0) {
  return [{ json: { message: '', skip: true } }];
}

// Determine highest priority
const priorityOrder = { 'CRITICAL': 0, 'HIGH': 1, 'MEDIUM': 2, 'LOW': 3 };
const maxPriority = triggers.reduce((max, t) =>
  (priorityOrder[t.priority] || 3) < (priorityOrder[max] || 3) ? t.priority : max,
  'LOW'
);

let message = '';

// Header
if (data.regimeChanged) {
  message += `VOL REGIME CHANGE -- ${data.timestamp} ET\n`;
  message += `${'='.repeat(40)}\n\n`;
  message += `Previous: ${data.prevRegime} (VIX ${data.prevVixLevel ? data.prevVixLevel.toFixed(1) : 'N/A'})\n`;
  message += `Current: ${data.currentRegimeLabel} (VIX ${data.vixPrice.toFixed(1)})\n\n`;
} else {
  message += `VOL REGIME ALERT -- ${maxPriority}\n`;
  message += `${'='.repeat(40)}\n\n`;
}

// Triggers
if (triggers.length > 0) {
  message += `ACTIONS REQUIRED:\n`;
  for (const trigger of triggers) {
    message += `\n[${trigger.priority}] ${trigger.detail}\n`;
    if (trigger.action) {
      message += `-> ${trigger.action}\n`;
    }
  }
  message += `\n`;
}

// Context
message += `---\n`;
message += `VIX: ${data.vixPrice.toFixed(2)} (${data.vixChangePct >= 0 ? '+' : ''}${data.vixChangePct.toFixed(1)}% today)\n`;
message += `Regime: ${data.currentRegimeLabel}\n`;
if (data.vix20DayAvg) message += `VIX 20-day avg: ${data.vix20DayAvg}\n`;
if (data.vix50DayAvg) message += `VIX 50-day avg: ${data.vix50DayAvg}\n`;
message += `Regime duration: ${data.regimeDuration}\n`;
message += `\n---\nAltamira Capital | Vol Regime Monitor`;

return [{ json: { message, priority: maxPriority } }];

// =============================================================
// FORMAT DAILY VOL SUMMARY FOR TELEGRAM
// =============================================================
// End-of-day summary sent at 4:00 PM ET.
// =============================================================

const data = $('Volatility Regime Engine').first().json;

let message = `VOL REGIME DAILY SUMMARY -- ${data.dateStr}\n`;
message += `${'='.repeat(40)}\n\n`;

message += `VIX Close:        ${data.vixPrice.toFixed(2)}  (${data.vixChangePct >= 0 ? '+' : ''}${data.vixChangePct.toFixed(1)}% today)\n`;
message += `VIX Regime:       ${data.currentRegimeLabel}\n`;
if (data.vix20DayAvg) message += `VIX 20-day avg:   ${data.vix20DayAvg}\n`;
if (data.vix50DayAvg) message += `VIX 50-day avg:   ${data.vix50DayAvg}\n`;
message += `Day Range:        ${data.vixDayLow.toFixed(2)} - ${data.vixDayHigh.toFixed(2)}\n`;
message += `Regime Duration:  ${data.regimeDuration}\n\n`;

// Today's trigger count
const triggerCount = data.triggers ? data.triggers.length : 0;
message += `Today's Triggers:  ${triggerCount}${triggerCount === 0 ? ' (quiet session)' : ''}\n`;
if (triggerCount > 0) {
  for (const t of data.triggers) {
    message += `  - ${t.detail}\n`;
  }
}
message += `\n`;

message += `Sizing Guidance:   ${data.sizingGuidance}\n\n`;

// 5-day VIX trend
if (data.vix5DayTrend && data.vix5DayTrend.length > 0) {
  message += `5-Day VIX Trend:\n`;
  for (const day of data.vix5DayTrend) {
    message += `  ${day.date}: ${day.close.toFixed(2)}\n`;
  }
  message += `  Today:  ${data.vixPrice.toFixed(2)}`;

  // Add trend direction
  if (data.vix5DayTrend.length > 0) {
    const firstDay = data.vix5DayTrend[0].close;
    if (data.vixPrice > firstDay * 1.05) {
      message += `   <-- trending higher, watch for thresholds`;
    } else if (data.vixPrice < firstDay * 0.95) {
      message += `   <-- trending lower, protection getting cheaper`;
    } else {
      message += `   <-- stable range`;
    }
  }
  message += `\n`;
}

message += `\n---\nAltamira Capital | Vol Regime Monitor (Daily Summary)`;

return [{ json: { message, dateStr: data.dateStr } }];

// =============================================================
// FORMAT GOOGLE SHEETS ROW
// =============================================================
// Logs vol regime data to the Vol Regime sheet.
// Written on every close execution AND on regime changes.
// =============================================================

const data = $('Volatility Regime Engine').first().json;

return [{
  json: {
    Date: data.dateStr,
    Time: data.timestamp,
    'VIX Level': data.vixPrice.toFixed(2),
    'VIX Change (%)': `${data.vixChangePct >= 0 ? '+' : ''}${data.vixChangePct.toFixed(1)}%`,
    'VIX Day High': data.vixDayHigh.toFixed(2),
    'VIX Day Low': data.vixDayLow.toFixed(2),
    'Regime': data.currentRegimeLabel,
    'Regime Changed': data.regimeChanged ? 'YES' : 'No',
    'Previous Regime': data.prevRegime,
    'VIX 20-Day Avg': data.vix20DayAvg || '',
    'VIX 50-Day Avg': data.vix50DayAvg || '',
    'Regime Duration': data.regimeDuration,
    'Triggers Fired': data.triggers ? data.triggers.length : 0,
    'Trigger Details': data.triggers ? data.triggers.map(t => t.type).join(', ') : '',
    'Sizing Guidance': data.sizingGuidance
  }
}];
